Copia a cadeia de caracteres do atalho de teclado exibido para o item de menu especificado para o buffer apontado pelo parâmetro text.

```foxpro
int _GetItemCmdKey(MENUID menuid, ITEMID itemid, char FAR *text)
MENUID menuid;            /* Menu identifier. */
ITEMID itemid;            /* Menu item identifier. */
char FAR *text;            /* Where to store the shortcut string. */
```

# Observações

_GetItemCmdKey( ) retorna o código de teclado interno do atalho de teclado. Se não houver atalho de teclado para o item de menu especificado, _GetItemCmdKey( ) retornará 0.

Para obter mais informações sobre como criar uma biblioteca de API e integrá-la ao Visual FoxPro, consulte Acessando a API do Visual FoxPro.

# Exemplo

O exemplo a seguir cria um menu com três itens, configurando um atalho de teclado para cada item. Ele usa _GetItemCmdKey( ) para exibir as teclas de atalho.

### Código do Visual FoxPro

```foxpro
SET LIBRARY TO GETICMDK
```

### Código C

```foxpro
#include <pro_ext.h>
void putLong(long n)
{
   Value val;
   val.ev_type = 'I';
   val.ev_long = n;
   val.ev_width = 10;
   _PutValue(&val);
}
FAR GetItemCmdKeyEx(ParamBlk FAR *parm)
{
   MENUID menuId;
   ITEMID itemId;
   Point loc;
   char FAR *shortcutString;
   int intKeyCode;
   menuId = _GetNewMenuId();
   _NewMenu(MPOPUP, menuId);
   itemId = _GetNewItemId(menuId);
   _NewItem(menuId, itemId, -2, "\\<1st item");
   _SetItemCmdKey(menuId, itemId, altKey | 0x78, "Alt+1");
   itemId = _GetNewItemId(menuId);
   _NewItem(menuId, itemId, -2, "\\<2nd item");
   _SetItemCmdKey(menuId, itemId, altKey | 0x79, "Alt+2");
   itemId = _GetNewItemId(menuId);
   _NewItem(menuId, itemId, -2, "\\<3rd item");
   _SetItemCmdKey(menuId, itemId, altKey | 0x7a, "Alt+3");
   loc.v = 10; loc.h = 20;
   _SetMenuPoint(menuId, loc);
   _ActivateMenu(menuId);
   if ((shortcutString = _Alloca(64)) == 0)
   {
      _DisposeMenu(menuId);
      _Error(182); // "Insufficient memory"
   }
   intKeyCode = _GetItemCmdKey(menuId, _GetItemId(menuId, 0),
      shortcutString);
   _PutStr("\nShortcut string = "); _PutStr(shortcutString);
   _PutStr("\nInternal key code ="); putLong(intKeyCode);
   intKeyCode = _GetItemCmdKey(menuId, _GetItemId(menuId, 1),
      shortcutString);
   _PutStr("\nShortcut string = "); _PutStr(shortcutString);
   _PutStr("\nInternal key code ="); putLong(intKeyCode);
   intKeyCode = _GetItemCmdKey(menuId, _GetItemId(menuId, 2),
      shortcutString);
   _PutStr("\nShortcut string = "); _PutStr(shortcutString);
   _PutStr("\nInternal key code ="); putLong(intKeyCode);
   _Execute("WAIT");
   _DisposeMenu(menuId);
}
FoxInfo myFoxInfo[] = {
   {"ONLOAD", (FPFI) GetItemCmdKeyEx, CALLONLOAD, ""},
};
FoxTable _FoxTable = {
   (FoxTable FAR *) 0, sizeof(myFoxInfo)/sizeof(FoxInfo), myFoxInfo
};
```

Compara cada byte em duas cadeias de caracteres terminadas em nulo, começando pelo byte mais à esquerda.

```foxpro
int _StrCmp(char FAR *string1, char FAR *string2)
char FAR *string1;         /* First comparison string. */
char FAR *string2;         /* Second comparison string. */
```

# Observações

_StrCmp( ) retorna 0 se string1 e string2 forem iguais, um número positivo se o primeiro byte diferente em string1 for maior que o byte correspondente em string2 ou um número negativo se o primeiro byte diferente em string1 for menor que o byte correspondente em string2.

Para obter mais informações sobre como criar uma biblioteca de API e integrá-la ao Visual FoxPro, consulte Acessando a API do Visual FoxPro.

# Exemplo

O exemplo a seguir usa _StrCmp( ) para comparar duas cadeias de caracteres passadas como parâmetros.

### Código do Visual FoxPro

```foxpro
SET LIBRARY TO STRCMP
? STRCMP("Hello, world.", "Hello, world.")  && matches; returns 0
? STRCMP("Hello, world.", "Hello, wurld.")  && no match; returns non-0
```

### Código C

```foxpro
#include <pro_ext.h>
void NullTerminate(Value FAR *cVal)
{
   if (!_SetHandSize(cVal->ev_handle, cVal->ev_length + 1))
   {
      _Error(182); // "Insufficient memory"
   }
   ((char FAR *) _HandToPtr(cVal->ev_handle))[cVal->ev_length] = '\0';
}
FAR Example(ParamBlk FAR *parm)
{
   int RetValue;
   NullTerminate(&parm->p[0].val);
   NullTerminate(&parm->p[1].val);
   _HLock(parm->p[0].val.ev_handle);
   _HLock(parm->p[1].val.ev_handle);
   RetValue = _StrCmp(_HandToPtr(parm->p[0].val.ev_handle),
      _HandToPtr(parm->p[1].val.ev_handle));
   _RetInt(RetValue, 10); // does return control here
   _HUnLock(parm->p[0].val.ev_handle);
   _HUnLock(parm->p[1].val.ev_handle);
}
FoxInfo myFoxInfo[] = {
   {"STRCMP", (FPFI) Example, 2, "C,C"},
};
FoxTable _FoxTable = {
   (FoxTable FAR *) 0, sizeof(myFoxInfo)/sizeof(FoxInfo), myFoxInfo
};
```

Retorna o canal de arquivo do arquivo memo associado à área de trabalho especificada.

```foxpro
FCHAN _MemoChan(int workarea)
int workarea;               /* Work area number. */
```

# Observações

Se nenhum banco de dados estiver aberto nessa área de trabalho ou se o banco de dados não tiver um arquivo memo, _MemoChan( ) retornará – 1.

Para obter mais informações sobre como criar uma biblioteca de API e integrá-la ao Visual FoxPro, consulte Acessando a API do Visual FoxPro.

# Exemplo

O exemplo a seguir recupera o conteúdo de um campo memo. _MemoChan( – 1) retorna um canal para o arquivo memo da área de trabalho atual. Esse FCHAN é usado como argumento para callbacks de E/S de arquivo de baixo nível da API.

### Código do Visual FoxPro

```foxpro
SET LIBRARY TO MEMOCHAN
CREATE TABLE WMemo (MemoField M)
APPEND BLANK
REPLACE MemoField WITH "Hello, World."
? GETMEMO(@MemoField)
```

### Código C

```foxpro
#include <pro_ext.h>
FAR FindMemoEx(ParamBlk FAR *parm)
{
   Locator FAR *memoFldLoc;
   FCHAN fchMemo;
   char FAR *memoContents;
   int memoLen;
   long loc;
   if ((fchMemo = _MemoChan(-1)) == -1)
   {
      _UserError("_MemoChan() failed");
   }
   memoFldLoc = &parm->p[0].loc;
   if ((loc = _FindMemo(memoFldLoc)) < 0)
   {
      _UserError("_FindMemo() failed");
   }
   if ((memoLen = _MemoSize(memoFldLoc)) < 0)
   {
      _UserError("_MemoSize() failed");
   }
   if ((memoContents = _Alloca(memoLen + 1)) == 0)
   {
      _Error(182); // "Insufficient memory"
   }
   _FSeek(fchMemo, loc, FS_FROMBOF);
   _FRead(fchMemo, memoContents, memoLen);
   memoContents[memoLen] = '\0';
   _RetChar(memoContents);
}
FoxInfo myFoxInfo[] = {
   {"GETMEMO", (FPFI) FindMemoEx, 1, "R"},
};
FoxTable _FoxTable = {
   (FoxTable FAR *) 0, sizeof(myFoxInfo)/sizeof(FoxInfo), myFoxInfo
};
```

Adiciona uma função manipuladora de ociosidade ao final da lista de manipuladores de eventos de ociosidade chamados quando o Visual FoxPro aguarda uma entrada do usuário ou o tempo limite de um evento.

```foxpro
unsigned int _ActivateIdle(FPFI handler)
FPFI handler               /* Event handler. */
```

# Observações

_ActivateIdle( ) retorna um identificador inteiro para essa rotina. Use o identificador para remover o manipulador de eventos de ociosidade do loop ocioso com _DeActivateIdle( ).

Para obter mais informações sobre como criar uma biblioteca de API e integrá-la ao Visual FoxPro, consulte Acessando a API do Visual FoxPro.

# Exemplo

O exemplo a seguir ativa um manipulador de eventos de ociosidade quando a biblioteca é carregada. O manipulador apenas imprime uma mensagem. Ele é desativado quando a biblioteca é descarregada.

### Código do Visual FoxPro

```foxpro
SET LIBRARY TO ACTIIDLE
WAIT WINDOW TO m.test TIMEOUT 5
SET LIBRARY TO
```

### Código C

```foxpro
#include <pro_ext.h>
static unsigned IdlerID;
//   This is the routine that is registered as an idle event handler.
void FAR IdleHandler(WHandle wh, EventRec *ev)
{
   _PutStr("\nIdleHandler() called.");
}
void FAR Activate(ParamBlk FAR *parm)
{
   IdlerID = _ActivateIdle((FPFI) IdleHandler);
}
//   When the library is unloaded we must deactivate the idle event
//   handlerin a CALLONUNLOAD function.
void FAR DeActivate(ParamBlk FAR *parm)
{
   _DeActivateIdle(IdlerID);
}
FoxInfo myFoxInfo[] = {
   {"ACTIVATE",  (FPFI) Activate, CALLONLOAD,   ""},
   {"DEACTIVATE",  (FPFI) DeActivate, CALLONUNLOAD, ""}
};
FoxTable _FoxTable = {
   (FoxTable FAR *) 0, sizeof(myFoxInfo)/sizeof(FoxInfo), myFoxInfo
};
```

Fecha a janela especificada e libera toda a memória associada a ela.

```foxpro
void _WClose(WHANDLE wh)
WHANDLE wh;            /* Window handle. */
```

# Observações

Se a janela estiver sendo exibida na tela, _WClose( ) a removerá da tela.

Para obter mais informações sobre como criar uma biblioteca de API e integrá-la ao Visual FoxPro, consulte Acessando a API do Visual FoxPro.

# Exemplo

O exemplo a seguir cria e exibe uma janela. Depois que o usuário pressiona uma tecla em resposta a um comando WAIT do Visual FoxPro, _WClose( ) fecha a janela.

### Código do Visual FoxPro

```foxpro
SET LIBRARY TO WCLOSE
```

### Código C

```foxpro
#include <pro_ext.h>
FAR Ex(ParamBlk FAR *parm)
{
   WHANDLE wh;
   int row, col;
   Rect r;
   wh = _WOpen(2, 2, 20, 70, 0, WINDOW_SCHEME, (Scheme FAR *) 0,
      WO_SYSTEMBORDER);
   _WShow(wh);
   _Execute("WAIT WINDOW 'Press any key to close window'");
   _WClose(wh);
}
FoxInfo myFoxInfo[] = {
   {"ONLOAD", (FPFI) Ex, CALLONLOAD, ""},
};
FoxTable _FoxTable = {
   (FoxTable FAR *) 0, sizeof(myFoxInfo)/sizeof(FoxInfo), myFoxInfo
};
```

```foxpro
oReportListener.OutputPage(;
                  nPageNo, ;
                  eDevice, ;
                  nDeviceType ;
                 [,nleft, nTop, nWidth, nHeight ;
                 [,nClipLeft,nClipTop, nClipWidth, nClipHeight]])
```

Fornece acesso à página atual ou ao intervalo completo de páginas de uma execução de relatório, de acordo com o valor da propriedade ListenerType.

Parâmetros:
- `nPageNo` — No modo de uma página por vez (valores 0 e 2 de ListenerType), ReportListener usa este parâmetro para fornecer o número da página atual à medida que prepara cada página para saída. Nesse momento, você pode solicitar que essa única página seja renderizada em outro dispositivo. No modo de todas as páginas de uma vez (valores 1 e 3 de ListenerType), você usa este parâmetro para enviar a ReportListener o número da página a ser renderizada. Para obter mais informações sobre os valores compatíveis de ListenerType, consulte Propriedade ListenerType.
- `eDevice` — Fornece um identificador, uma referência ou um nome de arquivo para o dispositivo no qual a saída é renderizada. Quando ListenerType é 0, ReportListener usa este parâmetro para fornecer um identificador gráfico GDI+ para a impressora atual. Quando ListenerType é 2, a saída não vai de fato para uma impressora, portanto ReportListener fornece o valor 0. No modo de todas as páginas de uma vez (valores 1 e 3), você usa este parâmetro para fornecer a ReportListener: um identificador GDI de impressora; um identificador gráfico GDI+ de outro dispositivo de saída; uma referência a um objeto derivado da classe base Shape ou Container do Visual FoxPro; ou um nome de arquivo. Você informa o tipo do valor eDevice por meio de um valor apropriado em nDeviceType.
- `nDeviceType` — Representa o tipo de dispositivo no qual a saída é renderizada. Valor Tipo de dispositivo -1 Nenhum dispositivo. ReportListener fornece esse valor ao disparar OutputPage em ListenerType 2. 0 hDC (identificador GDI). Você pode fornecer um identificador GDI a ReportListener para enviar a saída a outra impressora. 1 hGraphics (identificador gráfico GDI+). ReportListener fornece esse valor ao disparar OutputPage em ListenerType 0. Você pode fornecê-lo para enviar a saída a outro contexto GDI+, como uma janela. 2 oFoxControl. Use este valor para instruir ReportListener a criar uma visualização usando um controle Shape ou Container do Visual FoxPro. 100 Especifica um nome de arquivo a ser salvo como imagem EMF. 101 TIFF. 102 JPEG. 103 GIF. 104 PNG. 105 BMP. 201 Especifica uma página a ser acrescentada a um TIFF criado anteriormente, gerando um arquivo TIFF de várias páginas. Dica: ReportListener pode realizar otimização adicional desse formato quando esse valor é usado antes do término da execução do relatório. Para ListenerType 0 ou 2, o evento OutputPage ocorre durante esse período. Um exemplo é mostrado abaixo. Para ListenerType 1 ou 3, você pode chamar OutputPage durante o evento AfterReport para aproveitar a otimização.
- `[nleft, nTop, nWidth, nHeight,[nClipLeft,nClipTop, nClipWidth, nClipHeight]]` — Esses parâmetros opcionais não são relevantes quando nDeviceType é 2 (uma superfície de controle do Visual FoxPro). O primeiro conjunto de quatro coordenadas (nleft, nTop, nWidth, nHeight) especifica, em unidades de 1/960 de polegada (960 dpi), o retângulo no dispositivo atual em que essa ocorrência do elemento de layout será renderizada. O segundo conjunto (nClipLeft, nClipTop, nClipWidth, nClipHeight) permite que um dispositivo de saída de visualização indique que somente uma parte da página precisa ser atualizada.

Retorno: Nenhum.

Aplica-se a: `objeto ReportListener`.

Retorna o identificador de menu correspondente ao literal definido pelo sistema para o menu do sistema ou título de menu.

```foxpro
MENUID _MenuId(long literal)
long literal;                  /* System-defined literal. */
```

# Observações

Os literais são definidos no arquivo de inclusão da API PRO_EXT.H.

Para obter mais informações sobre como criar uma biblioteca da API e integrá-la ao Visual FoxPro, consulte Acessando a API do Visual FoxPro.

# Exemplo

O exemplo a seguir adiciona um título de menu ao menu do sistema. Em seguida, anexa a ele um menu suspenso com dois itens. _MenuId( ) é usada para obter o MENUID do menu do sistema.

### Código do Visual FoxPro

```foxpro
SET LIBRARY TO MENUID
```

### Código C

```foxpro
#include <pro_ext.h>
MENUID SysMenuId;
MENUID PopupId;
ITEMID PadId;
void putLong(long n)
{
   Value val;
   val.ev_type = 'I';
   val.ev_long = n;
   val.ev_width = 10;
   _PutValue(&val);
}
FAR onSelection(long menuId, long itemId)
{
   _PutStr("\nitemId = "); putLong(itemId);
}
void FAR StartUp()
{
   ITEMID Bar1Id;
   ITEMID Bar2Id;
   int Error;
   // Add new menu title to SYSMENU.
   SysMenuId = _MenuId(_SYSMENU);
   PadId = _GetNewItemId(SysMenuId);
   if (_NewItem(SysMenuId, PadId, _LASTITEM, "\\<Added menu title"))
   {
      _Error(623); /* "Menu item cannot be defined." */
   }
   // Define menu.
   PopupId = _GetNewMenuId();
   if (Error = _NewMenu(MPOPUP, PopupId))
   {
      _Error(-Error);
   }
   Bar1Id = _GetNewItemId(PopupId);
   // WARNING: Call _NewItem() before another _GetNewItemId().
   if (_NewItem(PopupId, Bar1Id, _LASTITEM, "\\<1st item"))
   {
      _Error(623); /* "Menu item cannot be defined." */
   }
   Bar2Id = _GetNewItemId(PopupId);
   if (_NewItem(PopupId, Bar2Id, _LASTITEM, "\\<2nd item"))
   {
      _Error(623); /* "Menu item cannot be defined." */
   }
   // Attach menu to menu title
   _SetItemSubMenu(SysMenuId, PadId, PopupId);
   // Set up selection action.
